#!/bin/bash
set -e

# Posterior Segment (Examination tab + printed case sheet):
# - Spelling fix: 'Dilation' -> 'Dilatation' throughout (stage toggle
#   labels, info banner, and the printed case sheet's stage suffix).
# - Added 'Arteriolar Attenuation' as a new Vessels finding option
#   (only shows in the With Dilatation pass, since Vessels isn't part
#   of the Without Dilatation struct list).
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/consultation/[id]"
echo "" | base64 -d > "app/consultation/[id]/examination-tab.js"
echo "Wrote app/consultation/[id]/examination-tab.js"

mkdir -p "app/print-templates"
echo "" | base64 -d > "app/print-templates/actions.js"
echo "Wrote app/print-templates/actions.js"

git add "app/consultation/[id]/examination-tab.js" "app/print-templates/actions.js"
git commit -m "Fix Dilation -> Dilatation spelling; add Arteriolar Attenuation to Vessels findings"
git push

echo "Done."
